PENDING_DEMAND_STATUSES = ("pending", "in_progress", "has_problems")


def fill_counters(apps, schema_editor):
    """Fill the new counters from the orders that already exist."""
    Order = apps.get_model("accounts", "Order")
    User = apps.get_model("accounts", "User")
    Product = apps.get_model("catalog", "Product")

    instant_products = {
        product.pk
        for product in Product.objects.filter(type="immediate").only("pk", "type")
    }

    totals = {}
    for order in Order.objects.all().iterator():
        entry = totals.setdefault(
            order.user_id,
            {
                "revenue": Decimal("0.00"),
                "profit": Decimal("0.00"),
                "orders": 0,
                "pending": 0,
            },
        )
        entry["revenue"] += Decimal(order.price)
        entry["profit"] += Decimal(order.sold_price or 0) - Decimal(order.price)
        entry["orders"] += 1
        if (
            order.status in PENDING_DEMAND_STATUSES
            and order.product_id not in instant_products
        ):
            entry["pending"] += 1

    for user in User.objects.all().iterator():
        entry = totals.get(user.pk)
        if not entry:
            continue
        user.total_revenue = entry["revenue"]
        user.net_profit = entry["profit"]
        user.orders_count = entry["orders"]
        user.pending_demand_orders = entry["pending"]
        user.save(
            update_fields=[
                "total_revenue",
                "net_profit",
                "orders_count",
                "pending_demand_orders",
            ]
        )


